import type { WorldState } from './model.js';

/** Code artifacts reflect actual scenario switches; they are inspected, never executed. */
export function renderGeneratedCode(id: string, title: string, world: WorldState): string {
  const f = world.radicals.failure;
  const endpoint = world.incidentals.endpoint;
  const snippets: Record<string, string> = {
    cache_inconsistency: `const key = ${f.tenantScoped ? "tenantId + ':' + entityId" : 'entityId'};\n${f.revokeChecked ? 'await access.authorise(userId, entityId);' : ''}\nconst cached = await cache.get(key);\nif (cached${f.readYourWrites ? ' && cached.version >= requiredVersion' : ''}) return cached;\nconst fresh = await db.read(entityId);\n${f.invalidationOrdered ? 'await cache.setIfNewer(key, fresh);' : 'await cache.set(key, fresh);'}\nreturn fresh;`,
    api_backward_compatibility: `const operationId = ${f.stableRetry ? 'request.intentId' : 'randomUUID()'};\nconst operation = await operations.accept(operationId);\nreturn { status: ${f.enumCompatible ? "'pending'" : "'queued'"},\n  amount: ${f.sameUnits ? 'operation.amountRubles' : 'operation.amountMinor'},\n  ${f.acceptsAsync ? 'operation_id: operation.id' : 'result: undefined'} };`,
    transaction_event_gap: `const intent = { ...event, eventId: event.id };\n${f.publishedBeforeCommit ? 'await queue.publish(event);' : ''}\nawait db.transaction(async tx => {\n  await tx.save(operation);\n  ${f.eventDurable ? 'await tx.outbox.insert(intent);' : ''}\n  ${f.ackBeforeCommit ? 'await queue.ack(deliveryId);' : ''}\n});\n${!f.publishedBeforeCommit ? `await queue.publish({ ...event, event_id: ${f.eventIdentityStable ? 'intent.eventId' : 'randomUUID()'} });` : ''}`,
    retry_storm: `const retries = { owners: ${Number(f.retryLayers)}, maxAttempts: 3, jitter: ${Boolean(f.jitter)}, retryPermanentErrors: ${Boolean(f.permanentRetried)} };\n${f.admissionBounded ? 'await durableQueue.reserveCapacity(intent.id);' : ''}\nawait durableQueue.enqueue(intent);\nreturn { accepted: true, operation_id: intent.id };`,
    stale_distributed_lock: `const token = await lease.acquire(resourceId);\nconst epoch = ${f.monotoneEpoch ? 'token.epoch' : '1'};\n${f.effectOutsideFence ? 'await provider.apply(resourceId);' : ''}\nawait db.${f.tokenCheckedOnCommit ? 'commitIfCurrentEpoch(resourceId, epoch)' : 'commitWithoutEpochCheck(resourceId)'};\n${f.ownerSpecificRelease ? 'await lease.releaseIfOwner(token);' : 'await lease.release(resourceId);'}`,
    schema_rollout: `const decoders = { v1: ${f.replaySupported ? 'readV1' : 'undefined'}, v2: ${f.readerSupportsNew ? 'readV2' : 'undefined'} };\nproducer.publish({ amount: 4200${f.unitTagged ? ", version: 2, unit: 'minor'" : ''} });\nconst rollbackDecoders = ${f.rollbackReader ? 'decoders' : '{ v1: readV1 }'};`,
    partial_dependency_failure: `${f.acceptedDurable ? 'await intents.save(intent);' : ''}\nconst policy = { retryBudget: ${f.retryBounded ? "'shared'" : "'per-path'"}, allowStaleFallback: ${Boolean(f.staleFallbackAllowed)} };\nconst result = await ${f.fallbackUsed ? 'fallbackStore.read(intent)' : 'dependency.read(intent, policy)'};\nreturn { accepted: true, result };`,
    state_race_navigation: `const owner = router.currentRoute;\nconst data = await api.read('${endpoint}');\n${f.routeGuard ? 'if (owner !== router.currentRoute) return;' : '// route owner не проверяется'}\nstore.set(${f.entityScoped ? 'entityId' : "'selected'"}, data);\n${f.subscriptionCleanup ? 'return () => unsubscribe(owner);' : '// subscription остаётся после перехода'}`,
    unnecessary_rerender: `const props = ${f.propsStable ? 'stableRowProps' : '{ ...row, onChange: () => update(row.id) }'};\nconst selected = store.subscribe(${f.subscriptionScoped ? 's => s.rows[row.id]' : 's => s'});\nconst derived = ${f.computationMemoized ? 'memoise(inputs, compute)' : 'compute(inputs)'};\n${f.layoutBatched ? 'measureAllRows(); updateAllStyles();' : 'for (const row of rows) { updateStyle(row); measure(row); }'}`,
    listener_leak: `const handler = () => refresh();\nwindow.addEventListener('resize', handler);\nconst timer = setInterval(refresh, 1000);\nreturn () => {\n  ${f.cleanup ? `window.removeEventListener('resize', ${f.callbackIdentityStable ? 'handler' : '() => refresh()'});` : '// listener не удаляется'}\n  ${f.timerCleared ? 'clearInterval(timer);' : '// interval продолжает работать'}\n  ${f.requestCancelled ? 'controller.abort();' : '// pending request остаётся активным'}\n};`,
    cache_state_invalidation: `const key = ${f.keyIncludesFilters ? '[userId, filters]' : "['list']"};\n${f.invalidationAfterCommit ? 'await api.save(input);\ncache.invalidate(key);' : 'cache.invalidate(key);\nawait api.save(input);'}\n${f.versionOrdered ? 'if (data.version < watermark) return;' : '// watermark не проверяется'}\ncache.${f.subscriptionsUpdated ? 'setAndNotify' : 'setSilently'}(key, data);`,
    api_contract_evolution: `const response = await api.post('${endpoint}', { key: ${f.stableRetry ? 'intent.id' : 'newId()'} });\n${f.acceptsAsync ? 'if (response.status === 202) poll(response.operation_id);' : 'if (!response.result) retryPost();'}\nconst allowedStatus = ${f.enumCompatible ? "['pending', 'queued', 'done']" : "['pending', 'done']"};\nconst amount = response.amount${f.sameUnits ? ' / response.unitScale' : ''};`,
    optimistic_update_failure: `const mutationId = ${f.retriesStable ? 'intent.id' : 'newId()'};\nconst previous = store.snapshot();\nstore.optimistic(mutationId, input);\ntry {\n  const saved = await api.save({ ...input, mutationId });\n  ${f.mutationIdentity ? 'if (saved.mutationId !== mutationId) return;' : '// completion identity не проверяется'}\n  ${f.authoritativeResponse ? 'store.confirm(mutationId, saved);' : 'store.confirm(mutationId, input);'}\n} catch { store.${f.rollbackScoped ? 'rollbackMutation(mutationId)' : 'restore(previous)'}; }`,
    frontend_performance_regression: `${Number(f.bundleKB) > 500 ? "import FullWorkspace from './full-workspace';" : "const FullWorkspace = lazy(() => import('./full-workspace'));"}\n${f.sequentialFetch ? 'const a = await readA(); const b = await readB();' : 'const [a, b] = await Promise.all([readA(), readB()]);'}\n${f.imageBlocking ? 'loadAllImagesBeforeHero();' : 'prioritiseHero(); deferBelowFoldImages();'}\n${Number(f.mainThreadMs) > 300 ? 'computeLargeDatasetSynchronously(a, b);' : 'await computeInChunks(a, b);'}`,
    accessibility_interaction: `${f.keyboardHandler ? '<button onClick={performAction}>' : '<div onClick={performAction}>'}\n  ${f.accessibleName ? 'Сохранить изменения' : '<Icon />'}\n${f.keyboardHandler ? '</button>' : '</div>'}\n<Dialog ${f.focusContained ? 'containFocus backgroundInert' : 'backgroundInteractive'} />\nonClose: ${f.focusReturned ? 'returnFocusToOpener()' : 'removeDialog()'}`,
    hydration_mismatch: `const initial = ${f.snapshotShared ? 'serverSnapshot' : 'latestClientStore'};\nconst label = ${f.deterministicMarkup ? 'initial.timestamp' : 'Date.now()'};\nconst preference = ${f.browserOnlyDeferred ? 'initial.preference; // browser preference after mount' : "localStorage.getItem('preference')"};\nreturn ${f.markupValid ? '<section><button>{label}</button></section>' : '<button><button>{label}</button></button>'};`,
    health_check_misconfiguration: `livenessProbe: ${f.livenessExternal ? '/health/dependency' : '/health/process'}\nreadinessProbe: ${f.readinessBeforeWarmup ? '/health/started' : '/health/local-resources-ready'}\nstartupBudgetSeconds: ${f.startupBudgetEnough ? 60 : 20}\ntermination: ${f.drainBeforeKill ? 'readiness=false → drain → stop' : 'stop immediately'}`,
    resource_throttling: `cpuThrottledPeriodsPercent: ${f.throttledPeriods}\nrunQueueMs: ${f.runQueueMs}\ngcPauseMs: ${f.gcPauseMs}\nioWaitMs: ${f.ioWaitMs}`,
  };
  return (
    snippets[id] ||
    `${title}\n${Object.entries(f)
      .map(([k, v]) => `${k} = ${JSON.stringify(v)}`)
      .join('\n')}`
  );
}
